#include "CSM_chiquisumother3d.h"
#include "csm_util.h"

typedef struct CSM3D_WriterTag {
    char *out;
    csm3d_u32 cap;
    csm3d_u32 pos;
    int failed;
} CSM3D_Writer;

static void csm3d_w_init(CSM3D_Writer *w, char *out, csm3d_u32 cap)
{
    w->out = out;
    w->cap = cap;
    w->pos = 0U;
    w->failed = 0;
    if (out != 0 && cap > 0U) {
        out[0] = '\0';
    }
}

static void csm3d_w_ch(CSM3D_Writer *w, char c)
{
    if (w->failed) {
        return;
    }
    if (w->out == 0 || w->pos + 1U >= w->cap) {
        w->failed = 1;
        return;
    }
    w->out[w->pos] = c;
    w->pos++;
    w->out[w->pos] = '\0';
}

static void csm3d_w_text(CSM3D_Writer *w, const char *s)
{
    csm3d_u32 i;

    if (s == 0) {
        return;
    }
    i = 0U;
    while (s[i] != '\0') {
        csm3d_w_ch(w, s[i]);
        if (w->failed) {
            return;
        }
        i++;
    }
}

static void csm3d_w_uint(CSM3D_Writer *w, csm3d_u32 value)
{
    char tmp[32];
    csm3d_u32 n;
    csm3d_u32 i;

    if (value == 0U) {
        csm3d_w_ch(w, '0');
        return;
    }

    n = 0U;
    while (value > 0U && n < (csm3d_u32)sizeof(tmp)) {
        tmp[n] = (char)('0' + (value % 10U));
        value = value / 10U;
        n++;
    }
    i = 0U;
    while (i < n) {
        csm3d_w_ch(w, tmp[n - 1U - i]);
        i++;
    }
}

static void csm3d_w_int(CSM3D_Writer *w, int value)
{
    long v;

    v = (long)value;
    if (v < 0L) {
        csm3d_w_ch(w, '-');
        v = -v;
    }
    csm3d_w_uint(w, (csm3d_u32)v);
}

static void csm3d_w_fx(CSM3D_Writer *w, csm3d_i32 value)
{
    char tmp[40];

    if (csm3d_fx_to_text(value, tmp, (csm3d_u32)sizeof(tmp)) == 0U) {
        w->failed = 1;
        return;
    }
    csm3d_w_text(w, tmp);
}

static void csm3d_write_meta(CSM3D_Writer *w, const char *tag, const char *value)
{
    if (value == 0 || value[0] == '\0') {
        return;
    }
    csm3d_w_text(w, tag);
    csm3d_w_ch(w, ' ');
    csm3d_w_text(w, value);
    csm3d_w_ch(w, '\n');
}

int csm3d_encode(const CSM3D_Doc *doc, char *out_text, csm3d_u32 out_cap, csm3d_u32 *out_len, CSM3D_Diagnostic *diag)
{
    CSM3D_Writer w;
    int r;
    int i;
    int f;
    int m;

    if (doc == 0 || out_text == 0 || out_cap == 0U) {
        csm3d_set_diag(diag, CSM3D_ERR_NULL, 0, -1, -1, "null encode argument");
        return CSM3D_ERR_NULL;
    }

    r = csm3d_validate(doc, diag);
    if (r != CSM3D_OK) {
        return r;
    }

    csm3d_w_init(&w, out_text, out_cap);
    csm3d_write_meta(&w, "$Date", doc->date);
    csm3d_write_meta(&w, "$Time", doc->time);
    csm3d_write_meta(&w, "$Filename", doc->filename);
    csm3d_write_meta(&w, "$Actor", doc->actor);

    csm3d_w_text(&w, "$Comments\n");
    if (doc->comments[0] != '\0') {
        csm3d_w_text(&w, doc->comments);
    } else {
        csm3d_w_text(&w, "Generated by CSM_chiquisumother3d");
    }
    csm3d_w_ch(&w, '\n');
    csm3d_w_ch(&w, '\n');

    csm3d_w_text(&w, "$FirstFrame ");
    if (doc->first_frame != 0) {
        csm3d_w_int(&w, doc->first_frame);
    } else {
        csm3d_w_int(&w, doc->frame[0].frame_number);
    }
    csm3d_w_ch(&w, '\n');

    csm3d_w_text(&w, "$LastFrame ");
    if (doc->last_frame != 0) {
        csm3d_w_int(&w, doc->last_frame);
    } else {
        csm3d_w_int(&w, doc->frame[doc->frame_count - 1].frame_number);
    }
    csm3d_w_ch(&w, '\n');

    if (doc->spine_links > 0) {
        csm3d_w_text(&w, "$SpineLinks ");
        csm3d_w_int(&w, doc->spine_links);
        csm3d_w_ch(&w, '\n');
    }

    csm3d_w_text(&w, "$Rate ");
    if (doc->rate > 0) {
        csm3d_w_int(&w, doc->rate);
    } else {
        csm3d_w_int(&w, 60);
    }
    csm3d_w_ch(&w, '\n');

    csm3d_w_text(&w, "$NumMarkers ");
    csm3d_w_int(&w, doc->marker_count);
    csm3d_w_ch(&w, '\n');

    csm3d_w_text(&w, "$Order\n");
    i = 0;
    while (i < doc->marker_count) {
        if (i > 0) {
            csm3d_w_ch(&w, ' ');
        }
        csm3d_w_text(&w, doc->marker_name[i]);
        i++;
    }
    csm3d_w_ch(&w, '\n');
    csm3d_w_ch(&w, '\n');

    csm3d_w_text(&w, "$Points\n");
    f = 0;
    while (f < doc->frame_count) {
        csm3d_w_int(&w, doc->frame[f].frame_number);
        m = 0;
        while (m < doc->marker_count) {
            csm3d_w_ch(&w, ' ');
            csm3d_w_fx(&w, doc->frame[f].point[m].x);
            csm3d_w_ch(&w, ' ');
            csm3d_w_fx(&w, doc->frame[f].point[m].y);
            csm3d_w_ch(&w, ' ');
            csm3d_w_fx(&w, doc->frame[f].point[m].z);
            m++;
        }
        csm3d_w_ch(&w, '\n');
        f++;
    }

    if (w.failed) {
        csm3d_set_diag(diag, CSM3D_ERR_OUTPUT_FULL, 0, -1, -1, "output buffer is too small");
        return CSM3D_ERR_OUTPUT_FULL;
    }

    if (out_len != 0) {
        *out_len = w.pos;
    }
    csm3d_diag_init(diag);
    return CSM3D_OK;
}
